import{_ as o,o as r,c as e,a2 as a}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"和 Bot 协作","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/working-with-bots.md","filePath":"zh/guides/working-with-bots.md","lastUpdated":1790952322000}'),s={name:"zh/guides/working-with-bots.md"};function d(l,t,n,i,h,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="和-bot-协作" tabindex="-1">和 Bot 协作 <a class="header-anchor" href="#和-bot-协作" aria-label="Permalink to &quot;和 Bot 协作&quot;">​</a></h1><p><a href="./quick-start.html">快速开始</a> 解决的是把 Bot 跑起来；这一页讲的是怎么用好它——什么任务适合交出去、请求怎么说、规则放在哪、什么时候该拆成两个 Bot——后半部分是配置参考：创建 Bot 和详情页每个 tab 的字段。</p><h2 id="什么样的任务适合交给-bot" tabindex="-1">什么样的任务适合交给 Bot <a class="header-anchor" href="#什么样的任务适合交给-bot" aria-label="Permalink to &quot;什么样的任务适合交给 Bot&quot;">​</a></h2><p>同时满足三个条件的任务，交给 Bot 最合适：</p><ul><li><strong>结果清楚。</strong> 你说得出做完之后应该存在什么——一份文件、一条消息、一张表。</li><li><strong>来源够得着。</strong> 涉及的文件、网站或对话是它真能访问到的：已上传进工作区、已接入的渠道或服务、或者是公开内容。</li><li><strong>产出好检查。</strong> 你一眼能看出结果对不对，复查的成本才低。</li></ul><p>三条都满足，也还是从只读开始：先让它读和整理，检查几次产出，再逐步放权。<a href="./use-cases.html">使用场景</a> 里的每个示例都是这么起步的。</p><h2 id="把请求说清楚" tabindex="-1">把请求说清楚 <a class="header-anchor" href="#把请求说清楚" aria-label="Permalink to &quot;把请求说清楚&quot;">​</a></h2><p>一个好的请求会回答五个问题——结果、来源、约束、形式、确认点。那张表在 <a href="./quick-start.html#第-4-步-交给它第一个任务">快速开始</a>；这里看两组实际对比。</p><div class="warning custom-block"><p class="custom-block-title">含糊</p><blockquote><p>帮我盯着科技新闻，有意思的发给我。</p></blockquote></div><p>没有来源（哪些网站、哪些仓库？），没有送达时间，「有意思」还是一个替你做的主观判断。每期简报都在碰运气。</p><p><strong>改成：</strong></p><div class="tip custom-block"><p class="custom-block-title">具体</p><blockquote><p>每个工作日早上 8 点，汇总我关注的这几个仓库过去 24 小时的 release 和重要 issue，整理成一条简报发给我。每条信息注明来源，不确定的内容直接说不确定，不要编造。</p></blockquote></div><div class="warning custom-block"><p class="custom-block-title">含糊</p><blockquote><p>把这个表格清理一下。</p></blockquote></div><p>「清理」没有定义：哪些行算脏数据、原文件能不能动、最后要交回什么？Bot 动手之前得连猜三次。</p><p><strong>改成：</strong></p><div class="tip custom-block"><p class="custom-block-title">具体</p><blockquote><p>把我刚上传的 CSV 里 email 列为空的行全部删掉。给我清洗后的文件，并告诉我删了多少行。不要修改原文件。</p></blockquote></div><p>两处改写的共同点：点名来源、限定动作、让结果一眼可验。</p><h2 id="长期规则放哪" tabindex="-1">长期规则放哪 <a class="header-anchor" href="#长期规则放哪" aria-label="Permalink to &quot;长期规则放哪&quot;">​</a></h2><p>两类指令，两个去处：</p><ul><li><strong>长期规则</strong> 写进 Bot 详情页的指令里——角色、格式标准、常设约束。之后每一次会话都生效。</li><li><strong>一次性要求</strong> 写在消息里——今天这份文件、这周的例外。</li></ul><p>一条纠正值得长期生效时，就把它升级：改写成持久规则，挪进指令，做法见 <a href="./quick-start.html#第-7-步-复盘-然后固化下来">快速开始</a> 第 7 步。整套流程反复出现时，存成 <a href="./skills.html">技能</a>，一句话就能唤起；希望 Bot 自己记得的偏好，交给 <a href="./memory.html">长期记忆</a>。</p><h2 id="什么时候拆成多个-bot" tabindex="-1">什么时候拆成多个 Bot <a class="header-anchor" href="#什么时候拆成多个-bot" aria-label="Permalink to &quot;什么时候拆成多个 Bot&quot;">​</a></h2><p>一个 Bot 负责一件事。职责单一的 Bot 积累的上下文会持续帮到它；什么都干的 Bot 会稀释自己的指令和记忆。<a href="./quick-start.html">快速开始</a> 和 <a href="./overview.html">概览</a> 都讲过这一点，这里只补一个实用判断：新需求的受众不同、来源不同，或者需要的权限不同，就该新建第二个 Bot。</p><p>每个 Bot 都有独立的工作区、记忆、渠道和权限边界，互相看不见对方。拆开也让权限更诚实——只读 release 动态的那个 Bot，永远不需要执行命令的权利。</p><h2 id="审批习惯" tabindex="-1">审批习惯 <a class="header-anchor" href="#审批习惯" aria-label="Permalink to &quot;审批习惯&quot;">​</a></h2><p>任务需要哪一级就给哪一级——工作区权限从聊天、读文件、写文件、执行命令到管理逐级授予，见 <a href="./access.html">访问控制</a>。</p><p>实际操作：</p><ol><li>新流程从只读开始，写入和执行类工具调用留在审批后面。</li><li>检查过前几次运行，再考虑放宽。</li><li>会离开工作区的动作——给别人发消息、任何对外操作——即使流程已经很熟，也继续留在审批后面。</li></ol><p>这和 <a href="./use-cases.html#从示例到日常使用">使用场景</a> 的检查清单是同一条路：多批几次请求，远比撤销一次写错便宜。</p><hr><h2 id="创建" tabindex="-1">创建 <a class="header-anchor" href="#创建" aria-label="Permalink to &quot;创建&quot;">​</a></h2><ol><li>侧栏进入 <strong>Bots</strong>。</li><li>点 <strong>Create Bot</strong>。</li><li>基本信息： <ul><li><strong>Display Name</strong>：对外的名字</li><li><strong>Avatar</strong>：头像 URL</li><li><strong>Timezone</strong>：可空；不填则继承用户或系统时区</li><li><strong>ACL Preset</strong>：如 <code>allow_all</code>（默认放行）、<code>private_only</code>（仅私聊）等快捷策略</li></ul></li><li>创建。</li></ol><hr><h2 id="详情页" tabindex="-1">详情页 <a class="header-anchor" href="#详情页" aria-label="Permalink to &quot;详情页&quot;">​</a></h2><p>点卡片进 <strong>详情</strong>，各 tab 管不同事：</p><table tabindex="0"><thead><tr><th>Tab</th><th>内容</th></tr></thead><tbody><tr><td><strong>Overview</strong></td><td>workspace runtime、库、渠道、记忆等健康检查</td></tr><tr><td><strong>General</strong></td><td>主模型/标题/生图、记忆/搜索/TTS 绑定、时区、语言、推理、危险区</td></tr><tr><td><strong>Desktop</strong></td><td>Workspace display runtime、有头浏览器、实时 display session</td></tr><tr><td><strong>Workspace</strong></td><td>容器型 workspace 起停、快照、导入导出</td></tr><tr><td><strong>Network</strong></td><td>Workspace 网络与 overlay provider 状态/动作</td></tr><tr><td><strong>Memory</strong></td><td>浏览、搜、建、改、压记忆</td></tr><tr><td><strong>Platforms</strong></td><td>各消息渠道（Telegram、Discord、飞书等）</td></tr><tr><td><strong>Access</strong></td><td>ACL 与默认通过/拒绝</td></tr><tr><td><strong>Tool Approval</strong></td><td>需要人类确认的工具审批设置</td></tr><tr><td><strong>Agents</strong></td><td>可为聊天 workspace 启用的 ACP 兼容编码智能体，如 Codex、Claude Code</td></tr><tr><td><strong>Connectors</strong></td><td>经 Connect-It 连接的第三方服务（OAuth 或 API Key）：状态、启停、重新授权、断开</td></tr><tr><td><strong>Hooks</strong></td><td>保存在 <code>/data/.memoh/hooks.json</code> 的 Bot 自动化规则</td></tr><tr><td><strong>MCP</strong></td><td>连接（Stdio/Remote/OAuth）</td></tr><tr><td><strong>Compaction</strong></td><td>会话压缩设置与记录</td></tr><tr><td><strong>Schedule</strong></td><td>cron 与日志</td></tr><tr><td><strong>Skills</strong></td><td>技能 Markdown</td></tr></tbody></table><p>Files、Terminal 以及桌面 / 浏览器面板在聊天的 workspace 区域里同样可用——想不离开对话就查看文件、跑 shell、盯着 Bot 的浏览器和桌面时，用聊天里的 workspace 侧栏。</p><hr><h2 id="核心先配什么" tabindex="-1">核心先配什么 <a class="header-anchor" href="#核心先配什么" aria-label="Permalink to &quot;核心先配什么&quot;">​</a></h2><ol><li>打开 Bot <strong>General</strong>，先管模型与各类绑定。</li><li><strong>Schedule</strong> 管周期性自主任务。</li><li><strong>Compaction</strong> 管会话写不长时的压缩。</li><li><strong>Access</strong> 在 ACL 预设之后细调。</li></ol><p>若这些资源还没有，先建好：</p><ul><li><a href="./../integrations/providers/llm.html">模型服务商与模型</a></li><li><a href="./../integrations/providers/memory/builtin.html">内置记忆提供方</a>（如用）</li><li><a href="./../integrations/providers/web-search.html">搜索提供方</a></li><li><a href="./../integrations/providers/tts/edge.html">TTS：Edge</a></li><li><a href="./acp.html">Agents / ACP</a></li></ul><hr><h2 id="general-字段" tabindex="-1">General 字段 <a class="header-anchor" href="#general-字段" aria-label="Permalink to &quot;General 字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Chat Model</strong></td><td>主对话模型</td></tr><tr><td><strong>Title Model</strong></td><td>可选，生成会话标题</td></tr><tr><td><strong>Image Generation Model</strong></td><td>可选，需带 <code>image-output</code> 的聊天模型</td></tr><tr><td><strong>Memory Provider</strong></td><td>长期记忆后端；内置类型还可自带记忆/向量模型</td></tr><tr><td><strong>Search Provider</strong></td><td>联网搜索用哪家</td></tr><tr><td><strong>TTS Model</strong></td><td>来自 TTS 提供方流程，不在普通 chat 模型服务商里选</td></tr><tr><td><strong>Timezone</strong></td><td>不填则用户时区再落到系统</td></tr><tr><td><strong>Language</strong></td><td>Bot 主用语</td></tr><tr><td><strong>Reasoning Effort</strong></td><td>当前 chat 模型有 <code>reasoning</code> 时可用；可选值随模型而定（如 <code>low</code> / <code>medium</code> / <code>high</code>）</td></tr></tbody></table><p>注意：</p><ul><li><strong>生图模型</strong> 故意与主聊天模型分开，好单独换「更擅长出图」的。</li><li><strong>TTS</strong> 用 <a href="./../integrations/providers/tts/edge.html">TTS 提供方</a> 所配置语音提供方的 <code>speech</code> 模型。</li><li>所选聊天模型的 <code>context_window</code> 会影响会话状态展示和 <a href="./compaction.html">会话压缩</a>。</li></ul><hr><h2 id="compaction-相关-此处指「会话」" tabindex="-1">Compaction 相关（此处指「会话」） <a class="header-anchor" href="#compaction-相关-此处指「会话」" aria-label="Permalink to &quot;Compaction 相关（此处指「会话」）&quot;">​</a></h2><p>这里说的是 <strong>当前会话</strong> 的上下文压短，不是改记忆条目的那种。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Compaction Enabled</strong></td><td>是否自动在会话里压摘要</td></tr><tr><td><strong>Compaction Threshold</strong></td><td>触发的估算 token 阈值</td></tr><tr><td><strong>Compaction Ratio</strong></td><td>压多狠</td></tr><tr><td><strong>Compaction Model</strong></td><td>可选，专门做摘要的模型</td></tr></tbody></table><p>细节见 <a href="./compaction.html">会话上下文压缩</a>。</p><hr><h2 id="访问与-acl" tabindex="-1">访问与 ACL <a class="header-anchor" href="#访问与-acl" aria-label="Permalink to &quot;访问与 ACL&quot;">​</a></h2><p>创建时先给一个 <strong>ACL 预设</strong>，之后在 <strong>Access</strong> 里微调。<strong>预设</strong> 给一版默认策略，<strong>Default Effect</strong> 管「没命中规则时」放行还是挡。</p><p><a href="./sessions.html">会话</a> 与 Discuss 的默认行为在那一页。若你用 API/自动化，配置里还可能有 <code>discuss_probe_model_id</code> 等进阶项，日常创建不必先动。</p><hr><h2 id="workspace-文件与终端" tabindex="-1">Workspace 文件与终端 <a class="header-anchor" href="#workspace-文件与终端" aria-label="Permalink to &quot;Workspace 文件与终端&quot;">​</a></h2><p>Workspace 文件和终端在聊天 workspace UI 里使用；前提是该 Bot 有可用的 workspace runtime。这里可以：</p><ul><li>浏览、编辑 workspace 文件</li><li>打开 workspace 内的终端会话</li><li>在开启 display 后使用浏览器/桌面相关工具</li></ul><p>文件流程见 <a href="./files.html">文件</a>，有头浏览器和桌面操作见 <a href="./browser-computer-use.html">Browser / Computer Use</a>。</p><hr><h2 id="删除" tabindex="-1">删除 <a class="header-anchor" href="#删除" aria-label="Permalink to &quot;删除&quot;">​</a></h2><p><strong>General</strong> 最下 <strong>Danger Zone</strong> -&gt; <strong>Delete Bot</strong>，会删掉该 Bot 相关数据（含 workspace 文件与记忆等），<strong>不可恢复</strong>。</p>',64)])])}const m=o(s,[["render",d]]);export{p as __pageData,m as default};
